-- Applied to production 2026-09-17. Canonical invoice status uses part_paid; adjustments use credit/write_off/debit.
alter table public.invoice_adjustments drop constraint if exists invoice_adjustments_kind_check;
alter table public.invoice_adjustments add constraint invoice_adjustments_kind_check check (kind in ('credit','write_off','debit'));
create or replace function public.refresh_invoice_balance(p_invoice uuid) returns void language plpgsql security definer set search_path=public as $$ declare v_effective_total numeric; v_paid numeric; v_status text; begin select greatest(0,total-coalesce((select sum(case when kind in ('credit','write_off') then amount when kind='debit' then -amount else 0 end) from public.invoice_adjustments where invoice_id=p_invoice),0)),status into v_effective_total,v_status from public.invoices where id=p_invoice; if v_status is null then raise exception 'Invoice not found'; end if; select coalesce(sum(case when status='succeeded' then amount when status='refunded' then -amount else 0 end),0) into v_paid from public.invoice_payments where invoice_id=p_invoice; update public.invoices set amount_paid=least(v_effective_total,greatest(0,v_paid)),status=case when v_status='void' then 'void' when v_effective_total-v_paid<=0 then 'paid' when v_paid>0 then 'part_paid' when due_date<current_date and v_status in ('sent','overdue','part_paid') then 'overdue' else v_status end,paid_at=case when v_effective_total-v_paid<=0 then coalesce(paid_at,now()) else null end,updated_at=now() where id=p_invoice; end $$;
create or replace function public.mark_overdue_invoices() returns integer language plpgsql security definer set search_path=public as $$ declare n integer; begin update public.invoices set status='overdue',updated_at=now() where due_date<current_date and amount_due>0 and status in ('sent','part_paid'); get diagnostics n=row_count; return n; end $$;
create or replace function public.record_invoice_payment(p_invoice uuid,p_amount numeric,p_method text default 'manual',p_reference text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare v_company uuid; v_id uuid; v_currency char(3); v_due numeric; begin if p_amount is null or p_amount<=0 then raise exception 'Payment amount must be greater than zero'; end if; select company_id,currency,amount_due into v_company,v_currency,v_due from public.invoices where id=p_invoice and status<>'void' for update; if v_company is null or not exists(select 1 from public.profiles where id=auth.uid() and company_id=v_company and role in ('owner','manager')) then raise exception 'Not authorised'; end if; if p_amount>v_due then raise exception 'Payment exceeds outstanding balance'; end if; insert into public.invoice_payments(company_id,invoice_id,amount,currency,method,reference,created_by,status) values(v_company,p_invoice,p_amount,v_currency,coalesce(nullif(trim(p_method),''),'manual'),nullif(trim(p_reference),''),auth.uid(),'succeeded') returning id into v_id; perform public.refresh_invoice_balance(p_invoice); return v_id; end $$;
revoke all on function public.refresh_invoice_balance(uuid) from public,anon,authenticated; grant execute on function public.refresh_invoice_balance(uuid) to service_role;
DO $do$ declare r record; cols text; idx_name text; begin for r in select c.oid,c.conrelid,c.conname,c.conkey,n.nspname,t.relname from pg_constraint c join pg_class t on t.oid=c.conrelid join pg_namespace n on n.oid=t.relnamespace where c.contype='f' and n.nspname='public' loop if not exists(select 1 from pg_index i where i.indrelid=r.conrelid and i.indisvalid and (i.indkey::smallint[])[0:cardinality(r.conkey)-1]=r.conkey) then select string_agg(quote_ident(a.attname),', ' order by u.ord) into cols from unnest(r.conkey) with ordinality u(attnum,ord) join pg_attribute a on a.attrelid=r.conrelid and a.attnum=u.attnum; idx_name:=left('idx_fk_'||r.relname||'_'||replace(r.conname,'_fkey',''),63); execute format('create index if not exists %I on %I.%I (%s)',idx_name,r.nspname,r.relname,cols); end if; end loop; end $do$;
